@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h2>Warehouse Dashboard</h2>

<div class="card mb-4">
    <div class="card-header">
        <strong>Current Site:</strong> @WarehouseState.SelectedWarehouseName
    </div>
    <div class="card-body">
        <h5 class="card-title">Inventory Alerts</h5>
        <p>
            Low-stock items:
            @if (AlertService.LowStockCount > 0)
            {
                <span class="badge bg-danger fs-6">@AlertService.LowStockCount items below minimum</span>
            }
            else
            {
                <span class="badge bg-success fs-6">All stock levels OK</span>
            }
        </p>
        <p class="text-muted">
            <small>Auto-refreshes every 10 seconds. Polling is active while this page is open.</small>
        </p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertDataChanged += _alertHandler;

        // Start polling while this page is visible
        AlertService.Subscribe();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertDataChanged -= _alertHandler;

        // Stop polling when user leaves the page
        AlertService.Unsubscribe();
    }
}

